internal fun calendarWeekRange(start:LocalDate):String {val end=start.plusDays(6);val format=DateTimeFormatter.ofPattern("MMM d");return if(start.year!=end.year)start.format(DateTimeFormatter.ofPattern("MMM d, yyyy"))+" – "+end.format(DateTimeFormatter.ofPattern("MMM d, yyyy"))else start.format(format)+" – "+end.format(format)}
