@Composable private fun CalendarMonthGrid(selected:LocalDate,first:LocalDate,events:List<CalendarOccurrence>,choose:(LocalDate)->Unit,open:(LocalDate)->Unit){val today=LocalDate.now();val colors=MaterialTheme.colorScheme;Column(Modifier.padding(horizontal=12.dp)){
