}}
@Composable private fun CalendarTimeline(date:LocalDate,events:List<CalendarOccurrence>,books:List<CalendarBook>,open:(CalendarOccurrence)->Unit,add:(Int)->Unit,compact:Boolean){val zone=ZoneId.systemDefault();val begin=date.atStartOfDay(zone).toInstant();val end=date.plusDays(1).atStartOfDay(zone).toInstant();val visible=events.filter{it.start.toInstant()<end&&it.end.toInstant()>begin}.sortedBy{it.start.toInstant()};val colors=MaterialTheme.colorScheme;val slot=60.dp;val gutter=if(compact)28.dp else 54.dp
 BoxWithConstraints(Modifier.fillMaxWidth().height(slot*24)){
  val width=maxWidth-gutter-4.dp
  repeat(24){hour->Row(Modifier.offset(y=slot*hour).fillMaxWidth().height(slot).clickable{add(hour)}){Text(if(compact)hour.toString()else calendarTime(LocalTime.of(hour,0)),Modifier.width(gutter).padding(top=2.dp,start=4.dp),style=MaterialTheme.typography.labelSmall,color=colors.onSurfaceVariant);HorizontalDivider(Modifier.padding(top=9.dp),color=colors.outlineVariant.copy(alpha=.45f))}}
  // Assign overlapping events separate columns, keeping each event's target unambiguous.
  CalendarRules.layout(visible).forEach{placement->val o=placement.occurrence;val lane=placement.column;val columns=placement.columns;val a=if(o.start.toInstant()<begin)LocalTime.MIDNIGHT else o.start.withZoneSameInstant(zone).toLocalTime();val b=if(o.end.toInstant()>=end)1440 else o.end.withZoneSameInstant(zone).toLocalTime().let{it.hour*60+it.minute};val minute=a.hour*60+a.minute;val height=maxOf(30,b-minute).dp;val color=calendarColor(books.firstOrNull{it.id==o.event.book}?.color?:0)
   Surface(onClick={open(o)},modifier=Modifier.offset(x=gutter+width/columns*lane,y=minute.dp+10.dp).width((width/columns-2.dp).coerceAtLeast(24.dp)).height(height-2.dp),shape=RoundedCornerShape(8.dp),color=color.copy(alpha=.25f),border=BorderStroke(1.dp,color.copy(alpha=.5f))){Column(Modifier.padding(6.dp)){Text(o.event.title,style=MaterialTheme.typography.labelMedium,fontWeight=FontWeight.SemiBold,maxLines=if(compact)2 else 3,overflow=TextOverflow.Ellipsis);if(height>48.dp)Text(calendarTime(o.start.withZoneSameInstant(zone).toLocalTime()),style=MaterialTheme.typography.labelSmall)}}
  }
  if(date==LocalDate.now()){val now=LocalTime.now();HorizontalDivider(Modifier.offset(y=(now.hour*60+now.minute).dp+10.dp).padding(start=gutter),thickness=2.dp,color=colors.error)}
 }
